var a=`1412-ota-ika`;var e=`world-1412`;var o=`TO`;var t=`oceania`;var c=4;var s=34;var l={en:`Ota Ika`,ua:`Ота іка`};var m={en:`Tongan ota ika: a cooling citrus-coconut fish salad, traditionally based on raw fish. This version starts with cooked fish.`,ua:`Тонганське ота іка: свіжий рибний салат із цитрусом та кокосом, традиційно із сирої риби. У цій версії риба попередньо приготовлена.`};var u=[{en:`Steam fish until its centre reaches 63°C, about 10–12 minutes. Spread in a shallow covered dish and chill promptly.`,ua:`Готуйте рибу на парі до 63°C у центрі приблизно 10–12 хвилин. Перекладіть у неглибокий накритий посуд і швидко охолодіть.`,t:[`steaming`],m:12,i:[[`mahi-mahi`,550,`g`]]},{en:`Cut cooked cold fish into cubes. Toss with lemon and lime juice; chill 10 minutes.`,ua:`Наріжте приготовлену холодну рибу кубиками. Змішайте з лимонним і лаймовим соком; охолодіть 10 хвилин.`,t:[`dicing`,`acid-marination`],m:10,i:[[`lemon-juice`,55,`ml`],[`lime-juice`,55,`ml`]]},{en:`Thinly slice onion and dice tomato and cucumber; fold in with the fish.`,ua:`Тонко наріжте цибулю, а помідор і огірок, кубиками; змішайте з рибою.`,t:[`dicing`,`mixing`],m:7,i:[[`red-onion`,80,`g`],[`tomato`,130,`g`],[`cucumber`,120,`g`]]},{en:`Mix in coconut cream and a pinch of salt. Serve chilled.`,ua:`Додайте кокосові вершки й дрібку солі. Подавайте охолодженим.`,t:[`folding-in`,`seasoning`],m:5,i:[[`coconut-cream`,250,`ml`],[`sea-salt`,3,`g`]]}];var d={slug:a,id:e,country:`TO`,region:t,servings:4,minutes:34,title:l,text:m,steps:u};export{o as country,d as default,e as id,s as minutes,t as region,c as servings,a as slug,u as steps,m as text,l as title};